function header(j, wanted) {
  const h = j?.payload?.headers ?? j?.headers;
  const wantedKey = wanted.toLowerCase();
  if (Array.isArray(h)) {
    const found = h.find(x => String(x.name || '').toLowerCase() === wantedKey);
    if (found) return found.value ?? '';
  } else if (h && typeof h === 'object') {
    const foundKey = Object.keys(h).find(k => k.toLowerCase() === wantedKey);
    if (foundKey) return h[foundKey] ?? '';
  }
  return j?.[wanted] ?? j?.[wanted.toLowerCase()] ?? '';
}
