  const messageId = j.id || j.messageId || j.threadId || '';
  const emailDate = j.internalDate || header(j, 'Date') || j.date || new Date().toISOString();
  for (const [property, binary] of Object.entries(item.binary || {})) {
    const fileName = binary.fileName || property;
    const mime = binary.mimeType || '';
    const isSheet = /\.(csv|xlsx?|xlsm)$/i.test(fileName) || /csv|spreadsheet|excel|sheet/i.test(mime);
    if (!isSheet) continue;
    out.push({
      json: { messageId, threadId: j.threadId || '', from, subject, emailDate, fileName, sourceProperty: property },
      binary: { data: binary }
    });
  }
}
